-- Altar Core: in-game mod menu, debug panel, commands, combos and 40 custom items.
-- Toggle the menu with F2 or by clicking the gem button on screen. F4 opens the console.
--
--   scripts/altar_data.lua      item list (generated by AltarModManager/tools/gen_items.py)
--   scripts/altar_items.lua     item effects, black hole VFX, animated pedestals
--   scripts/altar_combos.lua    Event Horizon and item combos
--   scripts/altar_commands.lua  command system, bosses / rooms / floors / characters
--   scripts/altar_oblivion.lua  OBLIVION secret boss and its cutscenes
--   scripts/altar_ui.lua        the Altar menu, overlay, banners and toasts

local mod = RegisterMod("Altar Core", 1)
local json = require("json")
local game = Game()

local A = {
	mod = mod,
	game = game,
	sfx = SFXManager(),
	json = json,
	VERSION = "1.1.0",
	godMode = false,
	phaseWalk = false,
	spikeShield = true, -- spiked rocks / spikes do no damage (Debug tab, "spikes" command)
	statBonus = { damage = 0, tears = 0, speed = 0, range = 0, shotspeed = 0, luck = 0 },
}

---------------------------------------------------------------------------
-- Crash guard: every Altar callback runs protected. An error is written to log.txt
-- (the Mod Manager shows these under Settings > Crash reports) and to the Altar
-- console once, instead of firing every frame or stopping the rest of the mod.
---------------------------------------------------------------------------

A.errors = {} -- "file:line" -> { count, msg }
do
	local addCallback = mod.AddCallback
	local traceback = debug and debug.traceback or function(msg) return tostring(msg) end

	local function report(tag, msg)
		local e = A.errors[tag]
		if e then
			e.count = e.count + 1
			return
		end
		A.errors[tag] = { count = 1, msg = msg }
		Isaac.DebugString("[Altar Core] ERROR in " .. tag .. ": " .. msg)
		pcall(function()
			if A.consoleLog then A.consoleLog("error in " .. tag .. ": " .. msg:match("^[^\n]*")) end
			if A.toast then A.toast("Altar hit an error - it kept running (F4 for details)") end
		end)
	end

	function mod.AddCallback(self, id, fn, ...)
		local info = debug and debug.getinfo and debug.getinfo(2, "Sl")
		local tag = info and (info.short_src:match("[^/\\]+$") .. ":" .. info.currentline) or ("callback " .. tostring(id))
		local function guarded(...)
			local res = table.pack(xpcall(fn, traceback, ...))
			if res[1] then return table.unpack(res, 2, res.n) end
			report(tag, tostring(res[2]))
		end
		return addCallback(self, id, guarded, ...)
	end
end

A.DATA = include("scripts.altar_data")
A.ITEM = {}
A.ALTAR_IDS = {}
for _, info in ipairs(A.DATA) do
	info.id = Isaac.GetItemIdByName(info.name)
	A.ITEM[info.key] = info.id
	A.ALTAR_IDS[info.id] = info
end

-- OBLIVION is spawned as a normal enemy (so the game's boss bar stays hidden in
-- favour of Altar's own), so anything that treats bosses specially asks this.
A.OBLIVION_TYPE = Isaac.GetEntityTypeByName("Oblivion")
function A.isBossLike(e)
	return e:IsBoss() or e.Type == A.OBLIVION_TYPE
end

-- Mod list written by Altar Mod Manager (AltarModManager/app)
A.modList = {}
do
	local ok, list = pcall(include, "altar_modlist")
	if ok and type(list) == "table" then A.modList = list end
end

---------------------------------------------------------------------------
-- Shared helpers
---------------------------------------------------------------------------

-- a burst of coloured sparks and a puff of light: the shared VFX for item moments
function A.burst(pos, r, g, b, n, speed)
	n, speed = n or 10, speed or 4
	local color = Color(r, g, b, 1, r * 0.5, g * 0.5, b * 0.5)
	for i = 1, n do
		local vel = Vector.FromAngle(i * 360 / n + math.random(-12, 12)):Resized(speed * (0.6 + math.random() * 0.7))
		local e = Isaac.Spawn(EntityType.ENTITY_EFFECT, EffectVariant.EMBER_PARTICLE, 0, pos, vel, nil)
		e.Color = color
	end
	local poof = Isaac.Spawn(EntityType.ENTITY_EFFECT, EffectVariant.POOF02, 0, pos, Vector.Zero, nil)
	poof.Color = Color(r, g, b, 0.8, r * 0.6, g * 0.6, b * 0.6)
	poof.SpriteScale = Vector(0.8, 0.8)
end

-- true when a spiked rock (Mines / Ashpit) is touching this spot
function A.nearSpikedRock(pos)
	local room = game:GetRoom()
	for _, off in ipairs({ Vector(0, 0), Vector(26, 0), Vector(-26, 0), Vector(0, 26), Vector(0, -26) }) do
		local g = room:GetGridEntityFromPos(pos + off)
		if g and g:GetType() == GridEntityType.GRID_ROCK_SPIKED then return true end
	end
	return false
end

function A.forEachPlayer(fn)
	for i = 0, game:GetNumPlayers() - 1 do
		fn(Isaac.GetPlayer(i), i)
	end
end

function A.anyPlayerHas(id)
	for i = 0, game:GetNumPlayers() - 1 do
		local p = Isaac.GetPlayer(i)
		if p:HasCollectible(id) then return p end
	end
end

function A.hsv(h, s, v)
	local i = math.floor(h * 6)
	local f = h * 6 - i
	local p, q, t = v * (1 - s), v * (1 - f * s), v * (1 - (1 - f) * s)
	i = i % 6
	if i == 0 then return v, t, p
	elseif i == 1 then return q, v, p
	elseif i == 2 then return p, v, t
	elseif i == 3 then return p, q, v
	elseif i == 4 then return t, p, v
	end
	return v, p, q
end

function A.refreshStats()
	A.forEachPlayer(function(p)
		p:AddCacheFlags(CacheFlag.CACHE_ALL)
		p:EvaluateItems()
	end)
end

function A.spawnItem(id, player)
	player = player or Isaac.GetPlayer(0)
	local pos = game:GetRoom():FindFreePickupSpawnPosition(player.Position + Vector(0, 60), 0, true)
	Isaac.Spawn(EntityType.ENTITY_PICKUP, PickupVariant.PICKUP_COLLECTIBLE, id, pos, Vector.Zero, nil)
	Isaac.Spawn(EntityType.ENTITY_EFFECT, EffectVariant.POOF01, 0, pos, Vector.Zero, nil)
end

local q4Cache
function A.getQ4List()
	if q4Cache then return q4Cache end
	q4Cache = {}
	local cfg = Isaac.GetItemConfig()
	for i = 1, cfg:GetCollectibles().Size - 1 do
		local item = cfg:GetCollectible(i)
		if item then
			local ok, good = pcall(function() return item.Quality == 4 and not item.Hidden end)
			if ok and good then q4Cache[#q4Cache + 1] = i end
		end
	end
	return q4Cache
end

function A.spawnRandomQ4(player, rng)
	local list = A.getQ4List()
	if #list == 0 then return end
	local pick = rng and (rng:RandomInt(#list) + 1) or math.random(#list)
	A.spawnItem(list[pick], player)
	A.sfx:Play(SoundEffect.SOUND_EDEN_GLITCH)
end

-- "#THE_SAD_ONION_NAME" -> "The Sad Onion"
local function pretty(s)
	s = tostring(s or "")
	if s:sub(1, 1) ~= "#" then return s end
	s = s:sub(2):gsub("_NAME$", ""):gsub("_DESCRIPTION$", ""):gsub("_DESC$", ""):gsub("_", " "):lower()
	return (s:gsub("(%a)([%w']*)", function(a, b) return a:upper() .. b end))
end

-- Every non-hidden collectible (vanilla + all mods), built once on first use.
local catalogue
function A.getCatalogue()
	if catalogue then return catalogue end
	catalogue = {}
	local cfg = Isaac.GetItemConfig()
	for i = 1, cfg:GetCollectibles().Size - 1 do
		local c = cfg:GetCollectible(i)
		if c then
			local ok, info = pcall(function()
				return { id = i, name = c.Name, desc = c.Description, gfx = c.GfxFileName, q = c.Quality,
					hidden = c.Hidden, active = c.Type == ItemType.ITEM_ACTIVE }
			end)
			if ok and info and not info.hidden then
				local altar = A.ALTAR_IDS[i]
				info.name = altar and altar.name or pretty(info.name)
				info.desc = altar and altar.desc or pretty(info.desc)
				info.altar = altar ~= nil
				info.q = info.q or 0
				if info.gfx and info.gfx ~= "" and not info.gfx:find("^gfx/") then
					info.gfx = "gfx/items/collectibles/" .. info.gfx
				end
				info.lname = info.name:lower()
				catalogue[#catalogue + 1] = info
			end
		end
	end
	return catalogue
end

include("scripts.altar_items")(A)
include("scripts.altar_fallen_sky")(A)
include("scripts.altar_combos")(A)
include("scripts.altar_commands")(A)
include("scripts.altar_oblivion")(A)
include("scripts.altar_ui")(A)

function mod:onGameStart(continued)
	if not continued then
		for k in pairs(A.statBonus) do A.statBonus[k] = 0 end
	end
	if EID and not A.eidDone then
		for _, info in ipairs(A.DATA) do EID:addCollectible(info.id, info.desc) end
		A.eidDone = true
	end
end
mod:AddCallback(ModCallbacks.MC_POST_GAME_STARTED, mod.onGameStart)

Isaac.DebugString("[Altar Core] loaded v" .. A.VERSION .. " with " .. #A.DATA .. " items")
